require_once dirname(__DIR__).'/includes/auth.php';require_once dirname(__DIR__).'/includes/functions.php';require_admin();$pdo=db();$stats=['Total Users'=>(int)$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn(),'Total Listings'=>(int)$pdo->query('SELECT COUNT(*) FROM listings')->fetchColumn(),'Pending'=>(int)$pdo->query("SELECT COUNT(*) FROM listings WHERE status='pending'")->fetchColumn(),'Suspicious'=>(int)$pdo->query("SELECT COUNT(*) FROM listings WHERE trust_status='suspicious'")->fetchColumn(),'High Risk'=>(int)$pdo->query("SELECT COUNT(*) FROM listings WHERE trust_status='high_risk'")->fetchColumn(),'Reports'=>(int)$pdo->query("SELECT COUNT(*) FROM reports WHERE status='open'")->fetchColumn(),'Completed Trades'=>(int)$pdo->query("SELECT COUNT(*) FROM trade_requests WHERE status='completed'")->fetchColumn()];$queue=$pdo->query("SELECT l.id,l.title,l.fraud_score,l.trust_status,l.created_at,u.name seller FROM listings l JOIN users u ON u.id=l.user_id WHERE l.status IN ('pending','flagged') ORDER BY l.fraud_score DESC,l.created_at DESC LIMIT 8")->fetchAll();$pageTitle='Admin Dashboard';include dirname(__DIR__).'/includes/header.php';?><div class="section-head"><div><h2>Admin dashboard</h2><p>Marketplace moderation, reports, analytics, and ML prediction logs.</p></div><div class="actions"><a class="btn btn-sm" href="/admin/fraud_queue.php">Fraud Queue</a><a class="btn btn-sm btn-light" href="/admin/reports.php">Reports</a><a class="btn btn-sm btn-light" href="/admin/users.php">Users</a><a class="btn btn-sm btn-light" href="/admin/listings.php">Listings</a></div></div><div class="stats"><?php foreach($stats as $k=>$v):?><div class="stat"><span class="muted"><?=e($k)?></span><strong><?=$v?></strong></div><?php endforeach;?></div><div class="section-head"><h2>Fraud queue preview</h2></div><div class="table-wrap"><table class="table"><tr><th>Product</th><th>Seller</th><th>Score</th><th>Trust</th><th>Date</th></tr><?php foreach($queue as $l):?><tr><td><a href="/listing.php?id=<?=$l['id']?>"><?=e($l['title'])?></a></td><td><?=e($l['seller'])?></td><td><?=e((string)$l['fraud_score'])?></td><td><?=e(trust_label($l['trust_status']??''))?></td><td><?=e($l['created_at'])?></td></tr><?php endforeach;?></table></div><?php include dirname(__DIR__).'/includes/footer.php';?>